mapper.select:
SELECT B.BOARD_ID, B.USER_ID, B.TITLE, B.CATEGORY, B.VIEW_COUNT, B.LIKE_COUNT, B.DISLIKE_COUNT, B.COMMENT_COUNT, B.IS_HOT, B.HAS_POLL, B.PRODUCT_ID, DATE_FORMAT(B.CREATED_AT, '%Y-%m-%d %H:%i:%s') AS CREATED_AT, U.NICKNAME AS nickName, U.PROFILE_IMG_URL AS profileImg, P.PRODUCT_NAME AS productName, (SELECT BI.IMG_URL FROM BOARD_IMG BI WHERE BI.BOARD_ID = B.BOARD_ID ORDER BY BI.SORT_ORDER ASC LIMIT 1) AS thumbUrl FROM BOARD B LEFT JOIN USER U ON B.USER_ID = U.USER_ID LEFT JOIN PRODUCT P ON B.PRODUCT_ID = P.PRODUCT_ID WHERE B.STATUS = 'ACTIVE' AND B.CATEGORY = #{category}
AND (B.TITLE LIKE CONCAT('%', #{keyword}, '%') OR B.CONTENT LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY B.LIKE_COUNT DESC, B.CREATED_AT DESC
ORDER BY B.CREATED_AT ASC
ORDER BY B.CREATED_AT DESC
LIMIT #{offset}, #{pageSize}

		SELECT COUNT(*) FROM BOARD_REACTION WHERE USER_ID = #{userId} AND TARGET
		= #{target} AND TYPE = #{type}  AND BOARD_ID = #{boardId}
       AND COMMENT_ID =
		#{commentId}

