mapper.update:
UPDATE BOARD
SET LIKE_COUNT = (
SELECT COUNT(*) FROM BOARD_REACTION
WHERE BOARD_ID = #{boardId} AND TYPE = 'LIKE' AND TARGET = 'BOARD'
),
DISLIKE_COUNT = (
SELECT COUNT(*) FROM BOARD_REACTION
WHERE BOARD_ID = #{boardId} AND TYPE = 'DISLIKE' AND TARGET = 'BOARD'
)
WHERE BOARD_ID = #{boardId}

mapper.select:
SELECT TYPE AS type, TARGET AS target,
BOARD_ID AS boardId, COMMENT_ID AS commentId
FROM BOARD_REACTION
WHERE USER_ID = #{userId}
AND BOARD_ID = #{boardId}

